const url = params.url;
if (!url) throw new Error('params.url required');
const method = (params.method || 'GET').toUpperCase();
const headers = params.headers || {};
const body = params.body;
const timeout = Number(params.timeout_ms ?? 30000);
const init = { method, headers: { 'User-Agent': 'WeBrain-Skill/1.0', ...headers } };
if (body !== undefined && method !== 'GET' && method !== 'HEAD') {
  if (typeof body === 'string') { init.body = body; }
  else { init.body = JSON.stringify(body); init.headers['Content-Type'] = init.headers['Content-Type'] || 'application/json'; }
}
const controller = new AbortController();
const timer = setTimeout(() => controller.abort(), timeout);
init.signal = controller.signal;
const resp = await fetch(url, init);
clearTimeout(timer);
const ct = resp.headers.get('content-type') || '';
let bodyOut;
if (ct.includes('application/json')) { try { bodyOut = await resp.json(); } catch { bodyOut = await resp.text(); } }
else { bodyOut = await resp.text(); if (bodyOut.length > 50000) bodyOut = bodyOut.slice(0, 50000) + '\n...[truncated]'; }
const respHeaders = {};
resp.headers.forEach((v, k) => { respHeaders[k] = v; });
return { url, method, status: resp.status, ok: resp.ok, headers: respHeaders, body: bodyOut };
